CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT, username TEXT UNIQUE, uuid TEXT, limit_gb REAL, expiry_days INTEGER, ips TEXT, connection_type TEXT, tls TEXT, port INTEGER, used_gb REAL DEFAULT 0, is_active INTEGER DEFAULT 1, last_active INTEGER, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, advanced_frag TEXT DEFAULT NULL, cipher_suites TEXT DEFAULT NULL, tls_mask TEXT DEFAULT NULL, fingerprint TEXT DEFAULT 'chrome', max_connections INTEGER, limit_req INTEGER, used_req INTEGER DEFAULT 0, ip_limit INTEGER DEFAULT NULL, active_ips TEXT DEFAULT NULL, block_porn INTEGER DEFAULT 0, block_ads INTEGER DEFAULT 0, frag_len TEXT DEFAULT '200-3000', frag_int TEXT DEFAULT '1-2', lifetime_used_gb REAL DEFAULT 0, user_proxy_ip TEXT DEFAULT NULL, user_proxy_iata TEXT DEFAULT NULL, user_socks5 TEXT DEFAULT NULL, auto_reset_vol_days INTEGER DEFAULT 0, auto_reset_req_days INTEGER DEFAULT 0, last_reset_vol_time INTEGER DEFAULT 0, last_reset_req_time INTEGER DEFAULT 0, auto_rotate_ip INTEGER DEFAULT 1, rotate_time INTEGER DEFAULT 0, ip_operator TEXT DEFAULT 'all', ip_count INTEGER DEFAULT 15, last_rotate_time INTEGER DEFAULT 0, auto_rotate_user_proxy INTEGER DEFAULT 0, start_on_first_connect INTEGER DEFAULT 0, first_connection_time INTEGER DEFAULT NULL, enable_direct INTEGER DEFAULT 1, allow_insecure INTEGER DEFAULT 0, ech_enabled INTEGER DEFAULT 1, ech_value TEXT DEFAULT NULL, reseller_id INTEGER DEFAULT NULL);
CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT);
CREATE TABLE IF NOT EXISTS admin_login_logs (id INTEGER PRIMARY KEY AUTOINCREMENT, ip TEXT, user_agent TEXT, status TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS vouchers (code TEXT PRIMARY KEY, limit_gb REAL, expiry_days INTEGER, is_used INTEGER DEFAULT 0, used_by TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS resellers (id INTEGER PRIMARY KEY AUTOINCREMENT, username TEXT UNIQUE, password_hash TEXT, credit_gb REAL DEFAULT 100, used_gb REAL DEFAULT 0, max_users INTEGER DEFAULT 50, is_active INTEGER DEFAULT 1, note TEXT DEFAULT '', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_sabi_users_uuid ON users(uuid);
CREATE INDEX IF NOT EXISTS idx_sabi_users_reseller ON users(reseller_id);
